#include <vector>
#include <unordered_map>
#include <algorithm>
#include <climits>

class Solution {
public:
    long long sumOfModes(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::unordered_map<int, int> counts;
        for (int i = 0; i < k; ++i) counts[nums[i]]++;

        auto get_mode = [&]() {
            int max_f = 0, best_val = INT_MAX;
            for (const auto& [val, f] : counts) {
                if (f > max_f || (f == max_f && val < best_val)) {
                    max_f = f;
                    best_val = val;
                }
            }
            return best_val;
        };

        long long ans = get_mode();
        for (int i = k; i < n; ++i) {
            counts[nums[i]]++;
            if (--counts[nums[i - k]] == 0) {
                counts.erase(nums[i - k]);
            }
            ans += get_mode();
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long sumOfModes(int[] nums, int k) {
        int n = nums.length;
        Map<Integer, Integer> counts = new HashMap<>();
        for (int i = 0; i < k; i++) {
            counts.put(nums[i], counts.getOrDefault(nums[i], 0) + 1);
        }

        long ans = getMode(counts);
        for (int i = k; i < n; i++) {
            counts.put(nums[i], counts.getOrDefault(nums[i], 0) + 1);
            int prev = counts.get(nums[i - k]);
            if (prev == 1) counts.remove(nums[i - k]);
            else counts.put(nums[i - k], prev - 1);
            ans += getMode(counts);
        }
        return ans;
    }

    private int getMode(Map<Integer, Integer> counts) {
        int maxF = 0, bestVal = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey(), f = entry.getValue();
            if (f > maxF || (f == maxF && val < bestVal)) {
                maxF = f;
                bestVal = val;
            }
        }
        return bestVal;
    }
}

var sumOfModes = function(nums, k) {
    const n = nums.length;
    const counts = new Map();
    for (let i = 0; i < k; i++) {
        counts.set(nums[i], (counts.get(nums[i]) || 0) + 1);
    }

    function getMode() {
        let maxF = 0, bestVal = Infinity;
        for (const [val, f] of counts.entries()) {
            if (f > maxF || (f === maxF && val < bestVal)) {
                maxF = f;
                bestVal = val;
            }
        }
        return bestVal;
    }

    let ans = getMode();
    for (let i = k; i < n; i++) {
        counts.set(nums[i], (counts.get(nums[i]) || 0) + 1);
        const prev = counts.get(nums[i - k]);
        if (prev === 1) counts.delete(nums[i - k]);
        else counts.set(nums[i - k], prev - 1);
        ans += getMode();
    }
    return ans;
};
